// Function to remove duplicate strings from an array
function removeDuplicates(arr) {
  if (!arr || arr.length === 0) {
    return [];
  }

  const seen = {};
  const result = [];

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    if (seen[item] === undefined) { // Bug: case-sensitive check
      seen[item] = true;
      result.push(item);
    }
  }
  return result;
}

